namespace EngiSentry.Tests
{
    internal static class UnitTests
    {
        private static void Assert(bool condition, string message) { if (!condition) throw new InvalidOperationException(message); }
        private static string[] ExpandedTags(string text)
        {
            EquipmentTagExpansionResult expansion = EquipmentTagExpander.Expand(EquipmentTagGrammar.Parse(text));
            Assert(expansion.Success, "Expected grouped expansion to succeed: " + text);
            return expansion.Members.Select(x => x.NormalizedMemberTag).ToArray();
        }
        private static string ExpansionFailure(string text)
        {
            EquipmentTagExpansionResult expansion = EquipmentTagExpander.Expand(EquipmentTagGrammar.Parse(text));
            return expansion.Success ? string.Empty : expansion.FailureReason ?? string.Empty;
        }
        private static bool ExpansionFailsClosed(string text, string reason)
        {
            EquipmentTagExpansionResult expansion = EquipmentTagExpander.Expand(EquipmentTagGrammar.Parse(text));
            return !expansion.Success && expansion.Members.Count == 0 && expansion.FailureReason == reason;
        }
        private static bool ExpansionMethods(string text, string method)
        {
            EquipmentTagExpansionResult expansion = EquipmentTagExpander.Expand(EquipmentTagGrammar.Parse(text));
            return expansion.Success && expansion.Members.All(x => x.ExpansionMethod == method);
        }

        private static string Sanitize(string value)
        {
            var builder = new StringBuilder(value.Length);
            foreach (char c in value) builder.Append(Array.IndexOf(Path.GetInvalidFileNameChars(), c) >= 0 ? '_' : c);
            return builder.ToString();
        }

        private static void PilotEquipmentCoordinateRegression()
        {
            var snapshot = new DrawingSnapshot();
            snapshot.TextEntities.Add(new TextSnapshot { Text = "P-01A", Handle = "EQ1", Layer = "EQ-TAG", SpaceKind = "Model", Height = 1, PositionX = 100, PositionY = 100 });
            snapshot.TextEntities.Add(new TextSnapshot { Text = "SU-01", Handle = "EQ2", Layer = "EQ-TAG", SpaceKind = "Model", Height = 1, PositionX = 200, PositionY = 200 });
            snapshot.TextEntities.Add(new TextSnapshot { Text = "TK-02", Handle = "EQ3", Layer = "EQ-TAG", SpaceKind = "Model", Height = 1, PositionX = 300, PositionY = 300 });
            snapshot.TextEntities.Add(new TextSnapshot { Text = "CPS-00-01", Handle = "SL1", Layer = "SLP-TXT", SpaceKind = "Model" });
            snapshot.TextEntities.Add(new TextSnapshot { Text = "CPS-00-05", Handle = "SL5", Layer = "SLP-TXT", SpaceKind = "Model" });
            snapshot.TextEntities.Add(new TextSnapshot { Text = "MP-00-01", Handle = "VP1", Layer = "VPORTS", SpaceKind = "Model" });
            snapshot.TextEntities.Add(new TextSnapshot { Text = "PK-0002", Handle = "VP2", Layer = "VPORTS", SpaceKind = "Paper" });
            snapshot.TextEntities.Add(new TextSnapshot { Text = "SU-01", Handle = "PT1", Layer = "Text", SpaceKind = "Paper" });
            snapshot.TextEntities.Add(new TextSnapshot { Text = "X= 5571950", Handle = "X1", Layer = "EQ-ID", SpaceKind = "Model", PositionX = 101, PositionY = 100 });
            snapshot.TextEntities.Add(new TextSnapshot { Text = "Y= 5282610", Handle = "Y1", Layer = "EQ-ID", SpaceKind = "Model", PositionX = 100, PositionY = 101 });
            snapshot.TextEntities.Add(new TextSnapshot { Text = "E. 1000", Handle = "E1", Layer = "EQ-ID", SpaceKind = "Model" });
            snapshot.TextEntities.Add(new TextSnapshot { Text = "N 2000", Handle = "N1", Layer = "EQ-ID", SpaceKind = "Model" });
            snapshot.TextEntities.Add(new TextSnapshot { Text = "X=bad", Handle = "BAD1", Layer = "EQ-ID", SpaceKind = "Model" });
            snapshot.TextEntities.Add(new TextSnapshot { Text = "Y= 12 extra", Handle = "BAD2", Layer = "EQ-ID", SpaceKind = "Model" });
            EngineeringDrawingModel model = SemanticExtractor.Extract(snapshot);
            Assert(model.EquipmentTags.Select(x => x.NormalizedTag).SequenceEqual(new[] { "P-01A", "SU-01", "TK-02" }), "Pilot equipment tags or layer/space exclusions failed.");
            Assert(model.Coordinates.Count == 4 && model.Coordinates.Single(x => x.SourceHandle == "X1").Axis == "E" && model.Coordinates.Single(x => x.SourceHandle == "X1").Value == 5571950m && model.Coordinates.Single(x => x.SourceHandle == "Y1").Axis == "N" && model.Coordinates.Single(x => x.SourceHandle == "Y1").Value == 5282610m, "Pilot X/Y coordinate parsing failed.");
            PlotPlanModel plan = PlotPlanBuilder.Build(EntityIndexer.Build(model), model, snapshot);
            Assert(plan.EquipmentPlacements.Count == 3 && plan.EquipmentPlacements.Single(x => x.NormalizedTag == "P-01A").PlacementStatus == "Complete", "Pilot DrawingTag placement or X/Y association failed.");

            var unowned = new DrawingSnapshot();
            unowned.TextEntities.Add(new TextSnapshot { Text = "P-90A", Handle = "OWNER:TAG", Layer = "EQ-TAG", SpaceKind = "Model", Height = 1, PositionX = 0, PositionY = 0 });
            unowned.TextEntities.Add(new TextSnapshot { Text = "X= 100", Handle = "OWNER:SLP-E", Layer = "SLP-ID", SpaceKind = "Model", PositionX = 0, PositionY = 0 });
            unowned.TextEntities.Add(new TextSnapshot { Text = "Y= 200", Handle = "TXT-N", Layer = "TXT-ID", SpaceKind = "Model", PositionX = 0, PositionY = 0 });
            unowned.TextEntities.Add(new TextSnapshot { Text = "X= 300", Handle = "PAPER-E", Layer = "EQ-ID", SpaceKind = "Paper", PositionX = 0, PositionY = 0 });
            unowned.TextEntities.Add(new TextSnapshot { Text = "Y= 400", Handle = "VP-N", Layer = "VPORTS", SpaceKind = "Model", PositionX = 0, PositionY = 0 });
            EngineeringDrawingModel unownedModel = SemanticExtractor.Extract(unowned);
            EquipmentPlacement unownedPlacement = PlotPlanBuilder.Build(EntityIndexer.Build(unownedModel), unownedModel, unowned).EquipmentPlacements.Single();
            Assert(unownedPlacement.PlacementStatus == "Incomplete" && unownedPlacement.Easting.Status == "Missing" && unownedPlacement.Northing.Status == "Missing", "Unowned SLP-ID, TXT-ID, Paper, or VPORTS coordinates completed EQ-TAG equipment.");

            var linked = new DrawingSnapshot();
            linked.TextEntities.Add(new TextSnapshot { Text = "P-91A", Handle = "OWNED:TAG", Layer = "EQ-TAG", SpaceKind = "Model", Height = 1, PositionX = 0, PositionY = 0 });
            linked.TextEntities.Add(new TextSnapshot { Text = "X= 500", Handle = "OWNED:E", Layer = "TXT-ID", SpaceKind = "Model", PositionX = 0, PositionY = 0 });
            linked.TextEntities.Add(new TextSnapshot { Text = "Y= 600", Handle = "OWNED:N", Layer = "TXT-ID", SpaceKind = "Model", PositionX = 0, PositionY = 0 });
            EngineeringDrawingModel linkedModel = SemanticExtractor.Extract(linked);
            EquipmentPlacement linkedPlacement = PlotPlanBuilder.Build(EntityIndexer.Build(linkedModel), linkedModel, linked).EquipmentPlacements.Single();
            Assert(linkedPlacement.PlacementStatus == "Complete" && linkedPlacement.Easting.SelectedSourceLayer == "TXT-ID" && linkedPlacement.Northing.SelectedSourceLayer == "TXT-ID", "Deterministically owned TXT-ID coordinates were rejected.");
        }

        public static int Main()
        {
            PilotEquipmentCoordinateRegression();
            CrossDocumentTests.Run();
            RevisionTests.Run();
            var snapshot = new DrawingSnapshot { FileName = "drawing.dwg", ScanTimestampUtc = new DateTime(2026, 9, 3, 12, 34, 56, 123, DateTimeKind.Utc) };
            Assert(snapshot.Layers != null && snapshot.BlockReferences != null, "Snapshot collections were not initialized.");
            Assert(Sanitize("A:B< C>") == "A_B_ C_", "Filename sanitization failed.");
            string filename = Sanitize(snapshot.FileName ?? "unnamed") + ".20260903T123456123Z.snapshot.json";
            Assert(filename == "drawing.dwg.20260903T123456123Z.snapshot.json", "Snapshot filename generation failed.");
            var serializer = new DataContractJsonSerializer(typeof(DrawingSnapshot));
            using (var stream = new MemoryStream())
            {
                serializer.WriteObject(stream, snapshot);
                string json = Encoding.UTF8.GetString(stream.ToArray());
                Assert(json.StartsWith("{", StringComparison.Ordinal), "Serialization did not produce JSON.");
                using (var input = new MemoryStream(Encoding.UTF8.GetBytes(json))) Assert(serializer.ReadObject(input) is DrawingSnapshot, "Serialized JSON could not be read.");
            }
            string existing = Path.GetTempFileName();
            try
            {
                ExternalDependencySnapshot found = DependencyClassifier.Classify("Font", "existing", existing);
                Assert(found.Status == "Found" && found.ExistsOnDisk == true && found.ResolvedPath == existing, "Resolved existing dependency classification failed.");
                string missing = Path.Combine(Path.GetDirectoryName(existing)!, "engi-sentry-missing-font.shx");
                ExternalDependencySnapshot absent = DependencyClassifier.Classify("Font", "missing", missing);
                Assert(absent.Status == "Missing" && absent.ExistsOnDisk == false && absent.ResolvedPath == missing, "Resolved missing dependency classification failed.");
                ExternalDependencySnapshot unresolved = DependencyClassifier.Classify("Font", "romans.shx", "romans.shx");
                Assert(unresolved.Status == "Unknown" && unresolved.ExistsOnDisk == null && unresolved.ResolvedPath == null, "Unresolved dependency classification failed.");
                ExternalDependencySnapshot absoluteMissing = DependencyClassifier.Classify("Font", "absolute-missing", missing);
                Assert(absoluteMissing.Status == "Missing" && absoluteMissing.ExistsOnDisk == false, "Absolute missing dependency classification failed.");
            }
            finally { File.Delete(existing); }
            var semanticSnapshot = new DrawingSnapshot();
            Assert(EquipmentTagGrammar.Parse("P-0201").NormalizedTag == "P-0201" && EquipmentTagGrammar.Parse("P-0201").GroupKind == EquipmentTagGroupKind.None, "Compact direct equipment grammar failed.");
            Assert(EquipmentTagGrammar.Parse("p0201").NormalizedTag == "P-0201", "Compact case normalization failed.");
            Assert(EquipmentTagGrammar.Parse("P-0201A").NormalizedTag == "P-0201A" && EquipmentTagGrammar.Parse("P-0201 A").NormalizedTag == "P-0201A", "Compact direct suffix grammar failed.");
            Assert(EquipmentTagGrammar.Parse("P-0201 A/B").NormalizedTag == "P-0201A/B" && EquipmentTagGrammar.Parse("P-0201A/B").GroupKind == EquipmentTagGroupKind.SlashList, "Compact slash-list grammar failed.");
            Assert(EquipmentTagGrammar.Parse("P-0201A1").NormalizedTag == "P-0201A1" && EquipmentTagGrammar.Parse("P-0201 A1").NormalizedTag == "P-0201A1", "Alphanumeric compact suffix grammar failed.");
            Assert(EquipmentTagGrammar.Parse("P-0201A1/B2").NormalizedTag == "P-0201A1/B2" && EquipmentTagGrammar.Parse("P-0201 A1/B2").GroupKind == EquipmentTagGroupKind.SlashList, "Alphanumeric compact slash-list grammar failed.");
            Assert(EquipmentTagGrammar.Parse("E-0201 A~F").NormalizedTag == "E-0201A~F" && EquipmentTagGrammar.Parse("E-0201 A~F").GroupKind == EquipmentTagGroupKind.AlphabeticRange, "Alphabetic-range recognition failed.");
            Assert(EquipmentTagGrammar.Parse("P-200-101A/B").NormalizedTag == "P-200-101A/B" && EquipmentTagGrammar.Parse("P-200-101A/B").GroupKind == EquipmentTagGroupKind.SlashList, "Three-part slash-list grammar failed.");
            foreach (string invalidTag in new[] { string.Empty, "ROAD-TO-UNIT", "P-0201 A/B~F", "P-0201 /", "P-0201 ~", "P-0201 A1~F1", "P-0201 A~F2", "P-0201 A1~F" }) { EquipmentTagParseResult? ignored; Assert(!EquipmentTagGrammar.TryParse(invalidTag, out ignored), "Malformed equipment tag was accepted: " + invalidTag); }
            Assert(ExpandedTags("P-0201").SequenceEqual(new[] { "P-0201" }) && ExpansionMethods("P-0201", "Direct"), "Direct shared expansion failed.");
            Assert(ExpandedTags("P-0201 A/B").SequenceEqual(new[] { "P-0201A", "P-0201B" }) && ExpandedTags("P-0201 A1/B2").SequenceEqual(new[] { "P-0201A1", "P-0201B2" }), "Compact shared slash expansion failed.");
            Assert(ExpandedTags("P-200-101A/B").SequenceEqual(new[] { "P-200-101A", "P-200-101B" }), "Three-part shared slash expansion failed.");
            Assert(ExpandedTags("E-0201 A~F").SequenceEqual(new[] { "E-0201A", "E-0201B", "E-0201C", "E-0201D", "E-0201E", "E-0201F" }) && ExpansionMethods("E-0201 A~F", "AlphabeticRangeExpansion"), "Alphabetic range shared expansion failed.");
            Assert(ExpandedTags("E-200-101A~C").SequenceEqual(new[] { "E-200-101A", "E-200-101B", "E-200-101C" }) && ExpandedTags("E-0201 A~Z").Length == 26, "Three-part or bounded alphabetic range expansion failed.");
            Assert(ExpansionFailure("E-0201 F~A") == "DescendingAlphabeticRange" && ExpansionFailure("E-0201 A~A") == "DegenerateAlphabeticRange" && ExpansionFailure("P-0201 A/A") == "DuplicateGroupedMember" && ExpansionFailure("P-0201 A/B/A") == "DuplicateGroupedMember" && ExpansionFailsClosed("E-0201 F~A", "DescendingAlphabeticRange") && ExpansionFailsClosed("E-0201 A~A", "DegenerateAlphabeticRange") && ExpansionFailsClosed("P-0201 A/A", "DuplicateGroupedMember") && ExpansionFailsClosed("P-0201 A/B/A", "DuplicateGroupedMember"), "Invalid grouped expansion did not fail closed.");
            string[] semanticTexts = { "P-200-101A", "P-200-101A/B", "E-200-104", "TK-200-101", "PK-200-103", "1200-ST-101", "1200-PL-101", "1200-DK-101", "E. 1438500", "E 1500000", "N. 1492000", "N 1503500", "T.O.P. EL. +10.030", "T.O.S. EL+18.000", "T.O.G. EL+6.300", "H.P.P. EL+6.100", "ROAD C.L.", "UNIT LIMIT", "UNIT LIMIT N. 1444000", "UNIT LIMIT E. 1416000", "1", "16", "A0", "1:200", "00", "2026", "XXXX" };
            for (int i = 0; i < semanticTexts.Length; i++) semanticSnapshot.TextEntities.Add(new TextSnapshot { Text = semanticTexts[i], Handle = (i + 1).ToString("X"), ObjectType = "TEXT", Layer = "NOTES", PositionX = i, PositionY = i, SpaceKind = "Model" });
            var semantic = SemanticExtractor.Extract(semanticSnapshot);
            Assert(semantic.EquipmentTags.Count == 5, "Equipment tag parsing failed.");
            Assert(semantic.EquipmentTags.Any(x => x.RawTag == "P-200-101A/B" && x.NormalizedTag == "P-200-101A/B" && x.EquipmentPrefix == "P" && x.UnitNumber == "200" && x.SequenceNumber == "101" && x.Suffix == "A/B"), "Grouped equipment tag parsing failed.");
            Assert(semantic.StructureTags.Count == 3 && semantic.StructureTags.Any(x => x.TypeCode == "DK"), "Structure tag parsing failed.");
            Assert(semantic.Coordinates.Count == 4 && semantic.Coordinates.Any(x => x.Axis == "E" && x.Value == 1438500m), "Coordinate parsing failed.");
            Assert(semantic.Elevations.Count == 4 && semantic.Elevations.Any(x => x.ElevationType == "HPP" && x.Value == 6.100m), "Elevation parsing failed.");
            Assert(semantic.RoadLabels.Count == 1, "Road label parsing failed.");
            Assert(semantic.BoundaryLabels.Count == 3 && semantic.BoundaryLabels.Count(x => x.ParseStatus == "Partial") == 1, "Boundary parsing failed.");
            var classificationSnapshot = new DrawingSnapshot();
            classificationSnapshot.TextEntities.Add(new TextSnapshot { Text = "1200-ST-101", Handle = "LS1", ObjectType = "TEXT", Layer = "NOTES" }); classificationSnapshot.TextEntities.Add(new TextSnapshot { Text = "1200-PL-101", Handle = "LS2", ObjectType = "TEXT", Layer = "NOTES" }); classificationSnapshot.TextEntities.Add(new TextSnapshot { Text = "1200-DK-101", Handle = "LS3", ObjectType = "TEXT", Layer = "NOTES" });
            classificationSnapshot.TextEntities.Add(new TextSnapshot { Text = "P-200-101A", Handle = "EQ1", ObjectType = "TEXT", Layer = "NOTES" }); classificationSnapshot.TextEntities.Add(new TextSnapshot { Text = "P-200-101A/B", Handle = "EQ2", ObjectType = "TEXT", Layer = "NOTES" }); classificationSnapshot.TextEntities.Add(new TextSnapshot { Text = "E-200-104", Handle = "EQ3", ObjectType = "TEXT", Layer = "NOTES" }); classificationSnapshot.TextEntities.Add(new TextSnapshot { Text = "TK-200-101", Handle = "EQ4", ObjectType = "TEXT", Layer = "NOTES" }); classificationSnapshot.TextEntities.Add(new TextSnapshot { Text = "PK-200-103", Handle = "EQ5", ObjectType = "TEXT", Layer = "NOTES" });
            classificationSnapshot.TextEntities.Add(new TextSnapshot { Text = "TK-200-101", Handle = "ST1", ObjectType = "TEXT", Layer = "STR" }); classificationSnapshot.TextEntities.Add(new TextSnapshot { Text = "PR-200-101", Handle = "ST2", ObjectType = "TEXT", Layer = "STR" }); classificationSnapshot.TextEntities.Add(new TextSnapshot { Text = "SH-200-101", Handle = "ST3", ObjectType = "TEXT", Layer = "STR" });
            classificationSnapshot.TextEntities.Add(new TextSnapshot { Text = "PR-200-101", Handle = "AM1", ObjectType = "TEXT", Layer = "NOTES" }); classificationSnapshot.TextEntities.Add(new TextSnapshot { Text = "SH-200-101", Handle = "AM2", ObjectType = "TEXT", Layer = "NOTES" }); classificationSnapshot.TextEntities.Add(new TextSnapshot { Text = "STR-200-101", Handle = "AM3", ObjectType = "TEXT", Layer = "NOTES" });
            var classificationModel = SemanticExtractor.Extract(classificationSnapshot);
            Assert(new[] { "LS1", "LS2", "LS3" }.All(handle => classificationModel.StructureTags.Any(x => x.SourceHandle == handle) && !classificationModel.EquipmentTags.Any(x => x.SourceHandle == handle)), "Legacy structure classification changed.");
            Assert(new[] { "EQ1", "EQ2", "EQ3", "EQ4", "EQ5" }.All(handle => classificationModel.EquipmentTags.Any(x => x.SourceHandle == handle) && !classificationModel.StructureTags.Any(x => x.SourceHandle == handle)), "Neutral equipment classification changed.");
            Assert(new[] { "ST1", "ST2", "ST3" }.All(handle => classificationModel.StructureTags.Any(x => x.SourceHandle == handle) && !classificationModel.EquipmentTags.Any(x => x.SourceHandle == handle)), "Explicit structural-layer classification failed.");
            Assert(new[] { "AM1", "AM2", "AM3" }.All(handle => !classificationModel.EquipmentTags.Any(x => x.SourceHandle == handle) && !classificationModel.StructureTags.Any(x => x.SourceHandle == handle)), "Neutral overlapping tags did not fail closed.");
            var equipmentListClassification = new DrawingSnapshot(); equipmentListClassification.TextEntities.Add(new TextSnapshot { Text="NAME", Layer="EQ-LIST", Handle="QL1", PositionX=0, PositionY=100 }); equipmentListClassification.TextEntities.Add(new TextSnapshot { Text="DESCRIPTION", Layer="EQ-LIST", Handle="QL2", PositionX=100, PositionY=100 }); equipmentListClassification.TextEntities.Add(new TextSnapshot { Text="INSTALLATION", Layer="EQ-LIST", Handle="QL3", PositionX=200, PositionY=100 }); equipmentListClassification.TextEntities.Add(new TextSnapshot { Text="PR-200-101", Layer="EQ-LIST", Handle="QL4", PositionX=0, PositionY=90 }); equipmentListClassification.TextEntities.Add(new TextSnapshot { Text="Pump", Layer="EQ-LIST", Handle="QL5", PositionX=100, PositionY=90 }); equipmentListClassification.TextEntities.Add(new TextSnapshot { Text="EL+10", Layer="EQ-LIST", Handle="QL6", PositionX=200, PositionY=90 }); var equipmentListClassificationModel = SemanticExtractor.Extract(equipmentListClassification); Assert(equipmentListClassificationModel.EquipmentTags.Any(x => x.SourceHandle == "QL4") && !equipmentListClassificationModel.StructureTags.Any(x => x.SourceHandle == "QL4") && equipmentListClassificationModel.EquipmentListEntries.Count == 1 && equipmentListClassificationModel.EquipmentListEntries.Single().Tag == "PR-200-101" && equipmentListClassificationModel.EquipmentListEntries.Single().SourceHandles.Contains("QL4"), "EQ-LIST classification did not retain equipment-list provenance.");
            var coordinateSnapshot = new DrawingSnapshot();
            coordinateSnapshot.TextEntities.Add(new TextSnapshot { Text="E. 1438500", Handle="CV1", ObjectType="TEXT" }); coordinateSnapshot.TextEntities.Add(new TextSnapshot { Text="E 1500000", Handle="CV2", ObjectType="TEXT" }); coordinateSnapshot.TextEntities.Add(new TextSnapshot { Text="N. 1492000", Handle="CV3", ObjectType="TEXT" }); coordinateSnapshot.TextEntities.Add(new TextSnapshot { Text="N 1503500", Handle="CV4", ObjectType="TEXT" }); coordinateSnapshot.TextEntities.Add(new TextSnapshot { Text="e=123.5", Handle="CV5", ObjectType="TEXT" }); coordinateSnapshot.TextEntities.Add(new TextSnapshot { Text="N = +456.25", Handle="CV6", ObjectType="TEXT" }); coordinateSnapshot.TextEntities.Add(new TextSnapshot { Text="  E. 789  ", Handle="CV7", ObjectType="TEXT" }); coordinateSnapshot.TextEntities.Add(new TextSnapshot { Text="E -12.5", Handle="CV8", ObjectType="TEXT" }); coordinateSnapshot.TextEntities.Add(new TextSnapshot { Text="N +123.5", Handle="CV9", ObjectType="TEXT" }); coordinateSnapshot.TextEntities.Add(new TextSnapshot { Text="E 1500,25", Handle="CV10", ObjectType="TEXT" }); coordinateSnapshot.TextEntities.Add(new TextSnapshot { Text="E 1,500,000", Handle="CV11", ObjectType="TEXT" }); coordinateSnapshot.TextEntities.Add(new TextSnapshot { Text="N 1,500,000.25", Handle="CV12", ObjectType="TEXT" });
            string[] coordinateTrailing = { "E 100 EXTRA", "N. 200 mm", "E 100 N 200", "E 100;", "N 200 TEXT" }; for (int i = 0; i < coordinateTrailing.Length; i++) coordinateSnapshot.TextEntities.Add(new TextSnapshot { Text=coordinateTrailing[i], Handle="CT" + i.ToString(), ObjectType="TEXT" });
            string[] coordinateMalformed = { "E 1,,2", "N 1,2,3", "E 1.2.3", "E 100,", "E 1,,500", "E 1,50,000", "E 1,500,", "N 1,500,00" }; for (int i = 0; i < coordinateMalformed.Length; i++) coordinateSnapshot.TextEntities.Add(new TextSnapshot { Text=coordinateMalformed[i], Handle="CM" + i.ToString(), ObjectType="TEXT" });
            string[] coordinateIncomplete = { "E", "N.", "E=", "N +", "E -" }; for (int i = 0; i < coordinateIncomplete.Length; i++) coordinateSnapshot.TextEntities.Add(new TextSnapshot { Text=coordinateIncomplete[i], Handle="CI" + i.ToString(), ObjectType="TEXT" });
            coordinateSnapshot.TextEntities.Add(new TextSnapshot { Text="UNIT LIMIT E. 1416000", Handle="BC1", ObjectType="TEXT", SpaceKind="Model" }); coordinateSnapshot.TextEntities.Add(new TextSnapshot { Text="UNIT LIMIT N. 1444000", Handle="BC2", ObjectType="TEXT", SpaceKind="Model" });
