            Assert(coordinateModel.Coordinates.Single(x => x.SourceHandle == "CV8").Value == -12.5m && coordinateModel.Coordinates.Single(x => x.SourceHandle == "CV9").Value == 123.5m && coordinateModel.Coordinates.Single(x => x.SourceHandle == "CV10").Value == 1500.25m && coordinateModel.Coordinates.Single(x => x.SourceHandle == "CV11").Value == 1500000m && coordinateModel.Coordinates.Single(x => x.SourceHandle == "CV12").Value == 1500000.25m, "Signed, decimal, or grouped coordinate parsing failed.");
